m as (select * from jsonb_each($j${"djer":["lost","An arm with gold bracelets was found in his Abydos tomb (1900); the arm itself was discarded, only the bracelets survive (Cairo)."],"djoser":["disputed","Body parts (incl. a left foot) were found in the Step Pyramid burial chamber; whether they are Djoser's is uncertain."],"menkaure":["disputed","Bones found in his pyramid were radiocarbon-dated to the Christian period, so they are not his."],"djedkare-isesi":["remains","A partial skeleton found in his pyramid at Saqqara is attributed to him."],"unas":["remains","Fragments of a mummy (skull, arm, shin) were found in his pyramid's burial chamber."],"teti":["remains","An arm and shoulder were found in his pyramid's burial chamber."],"pepi-i":["remains","Fragments of his mummy and canopic remains were found in his pyramid."],"merenre":["disputed","A mummy found in his pyramid may be his or a later intrusive burial."],"seqenenre-tao":["mummy","Royal Cache (DB320). Skull shows fatal axe and dagger wounds; CT-scanned 2021."],"ahmose-i":["mummy","Royal Cache (DB320); now in the NMEC, Cairo."],"amenhotep-i":["mummy","Royal Cache (DB320); never unwrapped, digitally unwrapped by CT in 2021."],"thutmose-i":["disputed","Mummy CG 61065 from the Royal Cache is labelled Thutmose I, but its age and arrow wound suggest it may be someone else."],"thutmose-ii":["mummy","Royal Cache (DB320)."],"thutmose-iii":["mummy","Royal Cache (DB320)."],"hatshepsut":["disputed","Mummy KV60-A was identified as her in 2007 from a matching tooth; widely accepted but still questioned by some."],"amenhotep-ii":["mummy","Found in his own tomb, KV35."],"thutmose-iv":["mummy","Found in the KV35 cache."],"amenhotep-iii":["mummy","Found in the KV35 cache."],"akhenaten":["disputed","The KV55 skeleton is Tutankhamun's father by DNA (2010) and often identified as Akhenaten; still debated."],"neferneferuaten-smenkhkare":["disputed","Some scholars identify the KV55 skeleton as Smenkhkare instead of Akhenaten."],"tutankhamun":["mummy","Still in his tomb KV62; CT-scanned 2005, DNA-tested 2010. Several forensic face reconstructions exist."],"ramesses-i":["disputed","A mummy returned from the Niagara Falls Museum (2003) may be Ramesses I; not proven. Luxor Museum."],"seti-i":["mummy","Royal Cache (DB320); one of the best-preserved royal mummies."],"ramesses-ii":["mummy","Royal Cache (DB320); examined in Paris in 1976."],"merneptah":["mummy","Found in the KV35 cache."],"seti-ii":["mummy","Found in the KV35 cache."],"siptah":["mummy","Found in the KV35 cache; deformed left foot."],"setnakht":["disputed","An unidentified mummy from KV35 has been proposed as Setnakht."],"ramesses-iii":["mummy","Royal Cache (DB320); CT (2012) shows his throat was cut."],"ramesses-iv":["mummy","Found in the KV35 cache."],"ramesses-v-viii":["mummy","Ramesses V and VI: mummies found in the KV35 cache. Ramesses VII and VIII: none found."],"ramesses-ix":["mummy","Royal Cache (DB320)."],"psusennes-i":["remains","Skeleton in a silver coffin with a gold mask, intact tomb at Tanis (1940)."],"amenemope-osorkon-the-elder-siamun":["remains","Amenemope: skeletal remains with a gold mask from his Tanis burial."],"meshwesh-kings-takelot-osorkon-shoshenq":["remains","Shoshenq II: skeleton in a falcon-headed silver coffin at Tanis."]}$j$::jsonb)), a as (select * from jsonb_each($j${"hor-aha":["Aha"],"djet":["Wadj","Uadji"],"den":["Dewen","Udimu"],"djoser":["Netjerikhet","Zoser"],"sneferu":["Snofru","Snefru"],"khufu":["Cheops"],"djedefre":["Radjedef"],"khafre":["Chephren","Rakhaef"],"menkaure":["Mycerinus"],"neferirkare":["Kakai"],"nyuserre":["Neuserre Ini"],"pepi-i":["Pepy I"],"pepi-ii":["Pepy II"],"intef-i":["Antef I"],"intef-ii":["Antef II"],"intef-iii":["Antef III"],"mentuhotep-ii":["Nebhepetre"],"amenemhat-i":["Amenemhet I","Ammenemes I"],"senusret-i":["Sesostris I"],"amenemhat-ii":["Amenemhet II","Ammenemes II"],"senusret-ii":["Sesostris II"],"senusret-iii":["Sesostris III"],"amenemhat-iii":["Amenemhet III","Ammenemes III"],"amenemhat-iv":["Amenemhet IV","Ammenemes IV"],"sobekneferu":["Neferusobek"],"theban-kings-intef-sobekemsaf":["Theban kings (Antef, Sobekemsaf…)"],"ahmose-i":["Amosis"],"amenhotep-i":["Amenophis I"],"thutmose-i":["Tuthmosis I","Thothmes I"],"thutmose-ii":["Tuthmosis II","Thothmes II"],"thutmose-iii":["Tuthmosis III","Thothmes III"],"amenhotep-ii":["Amenophis II"],"thutmose-iv":["Tuthmosis IV","Thothmes IV"],"amenhotep-iii":["Amenophis III"],"akhenaten":["Amenhotep IV","Akhenaton","Ikhnaton"],"tutankhamun":["Tutankhaten","Tutankhamen","King Tut"],"ramesses-i":["Ramses I","Rameses I"],"seti-i":["Sethos"],"ramesses-ii":["Ramses II","Rameses II"],"merneptah":["Merenptah"],"seti-ii":["Sethos"],"ramesses-iii":["Ramses III","Rameses III"],"ramesses-iv":["Ramses IV","Rameses IV"],"ramesses-v-viii":["Ramses V–VIII","Rameses V–VIII"],"ramesses-ix":["Ramses IX","Rameses IX"],"ramesses-x":["Ramses X","Rameses X"],"ramesses-xi":["Ramses XI","Rameses XI"],"shoshenq-i":["Sheshonq I","Shishak I"],"meshwesh-kings-takelot-osorkon-shoshenq":["Meshwesh kings (Takelot, Osorkon, Sheshonq…)","Meshwesh kings (Takelot, Osorkon, Shishak…)"],"piye":["Piankhi"],"shabaqo":["Shabaka"],"shabitqo":["Shebitku"],"taharqo":["Taharqa","Tirhakah"],"tantamani":["Tanutamun"],"psamtik-i":["Psammetichus I"],"necho-ii":["Nekau II"],"psamtik-ii":["Psammetichus II"],"apries":["Wahibre","Hophra"],"amasis":["Ahmose II"],"psamtik-iii":["Psammetichus III"],"nectanebo-i":["Nakhtnebef I"],"nectanebo-ii":["Nakhtnebef II"],"alexander-the-great":["Alexander III of Macedon"],"cleopatra-vii":["Cleopatra"],"saladin":["Salah ad-Din Yusuf ibn Ayyub"],"baybars":["al-Zahir Baybars"],"muhammad-ali":["Mehmet Ali Pasha"],"gamal-abdel-nasser":["Nasser"]}$j$::jsonb))
insert into public.rulers (slug,name,aliases,dynasty,era_id,reign_start,reign_end,certainty,is_group,mummy_status,mummy_note,sort)
select b.x->>0, b.x->>1, coalesce((select array_agg(v) from jsonb_array_elements_text(a.value) v),'{}'), b.x->>2,
 (select e.id from public.eras e where (b.x->>3)::int + least(5,((b.x->>4)::int-(b.x->>3)::int)/2.0) >= e.start_year and (b.x->>3)::int + least(5,((b.x->>4)::int-(b.x->>3)::int)/2.0) < e.end_year order by e.start_year limit 1),
 (b.x->>3)::int,(b.x->>4)::int,
 case when coalesce(b.x->>5,'') like '%a%' then 'approx' when coalesce(b.x->>5,'') like '%d%' then 'debated' else 'firm' end,
 coalesce(b.x->>5,'') like '%g%', coalesce(m.value->>0,'none'), m.value->>1, (b.o-1)::int
from b left join m on m.key=b.x->>0 left join a on a.key=b.x->>0
on conflict (slug) do update set name=excluded.name,aliases=excluded.aliases,dynasty=excluded.dynasty,era_id=excluded.era_id,reign_start=excluded.reign_start,reign_end=excluded.reign_end,certainty=excluded.certainty,is_group=excluded.is_group,mummy_status=excluded.mummy_status,mummy_note=excluded.mummy_note,sort=excluded.sort;
select count(*), count(era_id) from public.rulers;